<?php $id=(int)($_GET['id']??0);$r=null;if($id){$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([$id]);$r=$s->fetch();if(!$r)redirect('?page=users');}$error='';verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['full_name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$role=$_POST['role']??'';$status=$_POST['status']??'Active';$pass=$_POST['password']??'';if(!$email||$name===''||!in_array($role,['Administrator','Staff'],true)||!in_array($status,['Active','Inactive'],true)||(!$id&&strlen($pass)<10)||($pass!==''&&strlen($pass)<10))$error='Provide a name, valid email, role, status and password of at least 10 characters.';elseif($id===(int)user()['id']&&$status!=='Active')$error='You cannot deactivate your own account.';else{try{if($id){if($pass!=='')$s=$pdo->prepare('UPDATE users SET full_name=?,email=?,role=?,status=?,password_hash=? WHERE id=?');else$s=$pdo->prepare('UPDATE users SET full_name=?,email=?,role=?,status=? WHERE id=?');$args=[$name,$email,$role,$status];if($pass!=='')$args[]=password_hash($pass,PASSWORD_DEFAULT);$args[]=$id;$s->execute($args);}else{$s=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,role,status) VALUES(?,?,?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role,$status]);$id=(int)$pdo->lastInsertId();}log_activity($pdo,$r?'Updated staff account':'Created staff account','user',$id);flash('Staff account saved.');redirect('?page=users');}catch(PDOException $e){$error='That email address is already in use.';}}}layout_start($id?'Edit staff account':'Add staff member','users'); ?><div class="page-heading"><div><a class="back-link" href="?page=users">← Staff accounts</a><h1><?=$id?'Edit account':'Add staff member'?></h1></div></div><?php if($error): ?><div class="alert error"><?=h($error)?></div><?php endif; ?><section class="panel form-panel"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Full name<input name="full_name" required value="<?=h($r['full_name']??'')?>"></label><label>Email<input type="email" name="email" required value="<?=h($r['email']??'')?>"></label><label>Role<select name="role"><option <?=($r['role']??'Staff')==='Staff'?'selected':''?>>Staff</option><option <?=($r['role']??'')==='Administrator'?'selected':''?>>Administrator</option></select></label><label>Status<select name="status"><option <?=($r['status']??'Active')==='Active'?'selected':''?>>Active</option><option <?=($r['status']??'')==='Inactive'?'selected':''?>>Inactive</option></select></label><label class="span-two">New password <?=$id?'<small>(leave blank to keep current)</small>':''?><input type="password" name="password" <?=$id?'':'required'?> minlength="10" autocomplete="new-password"></label><div class="form-actions span-two"><a class="button ghost" href="?page=users">Cancel</a><button class="button primary">Save account</button></div></form></section><?php layout_end();
